(function(){"use strict";const CONFIG={duration:5e3,animationDuration:350};function getCartUrl(){if(typeof wc_add_to_cart_params!=="undefined"&&wc_add_to_cart_params.cart_url){return wc_add_to_cart_params.cart_url}if(typeof wc_cart_params!=="undefined"&&wc_cart_params.cart_url){return wc_cart_params.cart_url}if(typeof gstore_wc!=="undefined"&&gstore_wc.cart_url){return gstore_wc.cart_url}const cartLink=document.querySelector('a[href*="/carrinho"], a[href*="/cart"]');if(cartLink){return cartLink.href}return window.location.origin+"/carrinho/"}let toastElement=null;let dismissTimeout=null;let isHovered=false;function createToastElement(){if(toastElement)return toastElement;const toast=document.createElement("div");toast.className="Gstore-cart-toast";toast.setAttribute("role","alert");toast.setAttribute("aria-live","polite");toast.style.setProperty("--toast-duration",`${CONFIG.duration}ms`);toast.innerHTML=`\n            <div class="Gstore-cart-toast__header">\n                <div class="Gstore-cart-toast__status">\n                    <span class="Gstore-cart-toast__icon">\n                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">\n                            <polyline points="20 6 9 17 4 12"></polyline>\n                        </svg>\n                    </span>\n                    <h3 class="Gstore-cart-toast__title">Adicionado ao carrinho</h3>\n                </div>\n                <button type="button" class="Gstore-cart-toast__close" aria-label="Fechar notificação">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n                        <line x1="18" y1="6" x2="6" y2="18"></line>\n                        <line x1="6" y1="6" x2="18" y2="18"></line>\n                    </svg>\n                </button>\n            </div>\n            <div class="Gstore-cart-toast__content">\n                <div class="Gstore-cart-toast__image">\n                    <img src="" alt="" />\n                </div>\n                <div class="Gstore-cart-toast__details">\n                    <h4 class="Gstore-cart-toast__product-name"></h4>\n                    <div class="Gstore-cart-toast__product-meta">\n                        <span class="Gstore-cart-toast__product-price"></span>\n                        <span class="Gstore-cart-toast__product-qty"></span>\n                    </div>\n                </div>\n            </div>\n            <div class="Gstore-cart-toast__footer">\n                <button type="button" class="Gstore-cart-toast__btn Gstore-cart-toast__btn--continue">\n                    Continuar comprando\n                </button>\n                <a href="#" class="Gstore-cart-toast__btn Gstore-cart-toast__btn--cart">\n                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n                        <circle cx="9" cy="21" r="1"></circle>\n                        <circle cx="20" cy="21" r="1"></circle>\n                        <path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path>\n                    </svg>\n                    Ver carrinho\n                </a>\n            </div>\n            <div class="Gstore-cart-toast__progress">\n                <div class="Gstore-cart-toast__progress-bar"></div>\n            </div>\n        `;const closeBtn=toast.querySelector(".Gstore-cart-toast__close");closeBtn.addEventListener("click",hideToast);const continueBtn=toast.querySelector(".Gstore-cart-toast__btn--continue");continueBtn.addEventListener("click",hideToast);const cartBtn=toast.querySelector(".Gstore-cart-toast__btn--cart");if(cartBtn){cartBtn.href=getCartUrl()}toast.addEventListener("mouseenter",()=>{isHovered=true;clearTimeout(dismissTimeout)});toast.addEventListener("mouseleave",()=>{isHovered=false;scheduleDismiss()});document.body.appendChild(toast);toastElement=toast;return toast}function updateToastContent(productInfo){if(!toastElement)return;const imageEl=toastElement.querySelector(".Gstore-cart-toast__image img");const nameEl=toastElement.querySelector(".Gstore-cart-toast__product-name");const priceEl=toastElement.querySelector(".Gstore-cart-toast__product-price");const qtyEl=toastElement.querySelector(".Gstore-cart-toast__product-qty");if(imageEl&&productInfo.image){imageEl.src=productInfo.image;imageEl.alt=productInfo.name||""}if(nameEl){nameEl.textContent=productInfo.name||"Produto"}if(priceEl&&productInfo.price){priceEl.textContent=productInfo.price}if(qtyEl){const qty=productInfo.quantity||1;qtyEl.textContent=`${qty} ${qty>1?"unidades":"unidade"}`}}function extractProductInfo(addedButton){if(addedButton&&addedButton.gstoreToastProductInfo){return addedButton.gstoreToastProductInfo}const productCard=addedButton.closest(".Gstore-product-card, .product, li.product");if(!productCard){return{name:"Produto adicionado",quantity:1}}let name="";const titleEl=productCard.querySelector(".Gstore-product-card__title a, "+".woocommerce-loop-product__title, "+".product-title a, "+"h2.woocommerce-loop-product__title");if(titleEl){name=titleEl.textContent.trim()}let image="";const imgEl=productCard.querySelector(".Gstore-product-card__image img, "+".woocommerce-product-gallery__image img, "+".attachment-woocommerce_thumbnail, "+"img.wp-post-image");if(imgEl){image=imgEl.src}let price="";const priceEl=productCard.querySelector(".Gstore-product-card__price .woocommerce-Price-amount, "+".price ins .woocommerce-Price-amount, "+".price > .woocommerce-Price-amount, "+".price .amount");if(priceEl){price=priceEl.textContent.trim()}let quantity=1;const qtyInput=productCard.querySelector("input.qty");if(qtyInput){quantity=parseInt(qtyInput.value,10)||1}return{name:name,image:image,price:price,quantity:quantity}}function showToast(productInfo){createToastElement();clearTimeout(dismissTimeout);toastElement.classList.remove("is-visible","is-exiting","is-error");void toastElement.offsetWidth;const cartBtn=toastElement.querySelector(".Gstore-cart-toast__btn--cart");if(cartBtn){cartBtn.href=getCartUrl()}updateToastContent(productInfo);const progressBar=toastElement.querySelector(".Gstore-cart-toast__progress-bar");if(progressBar){progressBar.style.animation="none";void progressBar.offsetWidth;progressBar.style.animation=""}requestAnimationFrame(()=>{toastElement.classList.add("is-visible");scheduleDismiss()})}function hideToast(){if(!toastElement)return;clearTimeout(dismissTimeout);toastElement.classList.add("is-exiting");setTimeout(()=>{toastElement.classList.remove("is-visible","is-exiting")},CONFIG.animationDuration)}function scheduleDismiss(){if(isHovered)return;clearTimeout(dismissTimeout);dismissTimeout=setTimeout(hideToast,CONFIG.duration)}function handleAddedToCart(event,fragments,cart_hash,$button){const button=$button?$button[0]||$button.get(0):null;if(!button){const recentlyClicked=document.querySelector(".add_to_cart_button.added");if(recentlyClicked){const productInfo=extractProductInfo(recentlyClicked);showToast(productInfo)}else{showToast({name:"Produto adicionado ao carrinho",quantity:1})}return}const productInfo=extractProductInfo(button);showToast(productInfo)}function handleAddToCartError(){createToastElement();toastElement.classList.add("is-error");const titleEl=toastElement.querySelector(".Gstore-cart-toast__title");if(titleEl){titleEl.textContent="Erro ao adicionar"}showToast({name:"Não foi possível adicionar o produto. Tente novamente.",quantity:1})}function init(){if(typeof jQuery==="undefined"){console.warn("Gstore Cart Toast: jQuery não encontrado");return}jQuery(document.body).on("added_to_cart",handleAddedToCart);jQuery(document.body).on("wc_cart_button_error",handleAddToCartError);createToastElement()}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}window.GstoreCartToast={show:showToast,hide:hideToast}})();
